 }
 public static function list(Actor $a,?int $branch=null):array{Guard::cap($a,Capabilities::DAILY_SELF);$db=Db::wpdb();$where='c.company_id=%d';$args=[$a->companyId];if($branch){Guard::branch($a,$branch,$a->can(Capabilities::DAILY_OTHERS)?Capabilities::DAILY_OTHERS:Capabilities::DAILY_SELF);$where.=' AND c.branch_id=%d';$args[]=$branch;}if($a->can(Capabilities::DAILY_OTHERS)){$ids=HierarchyScope::visibleEmployeeIds($a,$branch);if(!$ids)return[];$where.=' AND c.employee_id IN ('.implode(',',array_fill(0,count($ids),'%d')).')';$args=array_merge($args,$ids);}else{$where.=' AND c.employee_id=%d';$args[]=$a->employeeId;}return(array)$db->get_results($db->prepare("SELECT c.*,e.employee_code,e.full_name employee_name,e.designation_code,e.reporting_designation_code,r.id initial_request_id,r.status initial_request_status FROM ".Db::table('daily_cycles')." c JOIN ".Db::table('employees')." e ON e.id=c.employee_id AND e.company_id=c.company_id LEFT JOIN ".Db::table('daily_requests')." r ON r.daily_cycle_id=c.id AND r.type='initial' WHERE {$where} ORDER BY c.business_date DESC,c.id DESC LIMIT 100",...$args),ARRAY_A);}
 public static function detail(Actor $a,int $id):array{$c=self::cycle($a,$id);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;if((int)$c['employee_id']!==$a->employeeId)HierarchyScope::assertCanViewEmployee($a,(int)$c['employee_id']);Guard::branch($a,(int)$c['branch_id'],$cap);$db=Db::wpdb();$requests=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('daily_requests')." WHERE daily_cycle_id=%d ORDER BY id",$id),ARRAY_A);foreach($requests as&$r){$r['lines']=(array)$db->get_results($db->prepare("SELECT l.id,l.product_id,p.name product_name,p.batch_tracking,l.quantity FROM ".Db::table('daily_request_lines')." l JOIN ".Db::table('products')." p ON p.id=l.product_id WHERE l.daily_request_id=%d ORDER BY l.id",(int)$r['id']),ARRAY_A);$r['issued_lines']=(array)$db->get_results($db->prepare("SELECT il.*,p.name product_name,b.batch_no,b.expires_on FROM ".Db::table('daily_issue_lines')." il JOIN ".Db::table('products')." p ON p.id=il.product_id LEFT JOIN ".Db::table('batches')." b ON b.id=il.batch_id WHERE il.daily_request_id=%d ORDER BY il.id",(int)$r['id']),ARRAY_A);}unset($r);$evening=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d",$id),ARRAY_A);if($evening)$evening['lines']=(array)$db->get_results($db->prepare("SELECT el.*,p.name product_name,b.batch_no FROM ".Db::table('evening_lines')." el JOIN ".Db::table('products')." p ON p.id=el.product_id LEFT JOIN ".Db::table('batches')." b ON b.id=el.batch_id WHERE el.evening_settlement_id=%d ORDER BY el.id",(int)$evening['id']),ARRAY_A);return['cycle'=>$c,'requests'=>$requests,'evening'=>$evening?:null];}
 public static function create(Actor $a,int $branch,int $employee,string $date,array $lines):array{$date=Input::date($date,'Daily Order business date');$cap=$employee===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;if($employee!==$a->employeeId)HierarchyScope::assertCanViewEmployee($a,$employee);Guard::branch($a,$branch,$cap);BranchDayGuard::assertOpen($a,$branch,$date);if(!$lines)throw new DomainException('Daily Order needs product lines.');$db=Db::wpdb();$emp=$db->get_row($db->prepare("SELECT id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND assigned_branch_id=%d AND status='active'",$employee,$a->companyId,$branch),ARRAY_A);if(!$emp)throw new DomainException('Target employee not active in branch.');
 $attendance=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('attendance')." WHERE company_id=%d AND branch_id=%d AND employee_id=%d AND business_date=%s AND check_in_at IS NOT NULL AND check_in_lat IS NOT NULL AND check_in_lng IS NOT NULL",$a->companyId,$branch,$employee,$date));
 if(!$attendance)throw new DomainException('GPS attendance check-in required before Morning Product Issue.','daily_attendance_required',409);
 return Transaction::run(function()use($a,$branch,$employee,$date,$lines,$db){$c=Db::table('daily_cycles');if((int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$c} WHERE company_id=%d AND employee_id=%d AND business_date=%s",$a->companyId,$employee,$date)))throw new DomainException('Daily Order already exists.','daily_duplicate',409);Db::mustInsert($db,$c,['company_id'=>$a->companyId,'branch_id'=>$branch,'employee_id'=>$employee,'business_date'=>$date,'status'=>'morning_draft','created_by'=>$a->employeeId,'created_at'=>Db::now()],'Daily Order already exists.','daily_duplicate');$cid=(int)$db->insert_id;Db::mustInsert($db,Db::table('daily_requests'),['daily_cycle_id'=>$cid,'type'=>'initial','status'=>'draft','requested_by'=>$a->employeeId,'created_at'=>Db::now()]);$rid=(int)$db->insert_id;$seen=[];foreach($lines as$x){$pid=(int)($x['product_id']??0);$qty=(float)($x['quantity']??0);if(!$pid||$qty<=0)throw new DomainException('Invalid Daily Order line.');if(isset($seen[$pid]))throw new DomainException('Duplicate product in Daily Order request.','duplicate_daily_line',422);$seen[$pid]=1;StockService::product($a,$pid);Db::mustInsert($db,Db::table('daily_request_lines'),['daily_request_id'=>$rid,'product_id'=>$pid,'batch_id'=>null,'quantity'=>$qty]);}Audit::add($a,'daily_order.create','daily_cycle',$cid,['branch_id'=>$branch,'employee_id'=>$employee]);return['id'=>$cid,'request_id'=>$rid,'status'=>'morning_draft'];});}
 public static function submit(Actor $a,int $id):array{return Transaction::run(function()use($a,$id){$c=self::cycle($a,$id,true);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;Guard::branch($a,(int)$c['branch_id'],$cap);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='morning_draft')throw new DomainException('Daily Order not draft.');$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('daily_requests')." WHERE daily_cycle_id=%d AND type='initial'",$id),ARRAY_A);if(!$r||$r['status']!=='draft')throw new DomainException('Initial request is not draft.','daily_request_state_invalid',409);Db::mustUpdate($db,Db::table('daily_requests'),['status'=>'submitted'],['id'=>(int)$r['id']]);Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'stock_requested'],['id'=>$id]);return['id'=>$id,'status'=>'stock_requested'];});}
 public static function additional(Actor $a,int $id,array $lines):array{return Transaction::run(function()use($a,$id,$lines){$c=self::cycle($a,$id,true);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;Guard::branch($a,(int)$c['branch_id'],$cap);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='issued')throw new DomainException('Additional stock only after issue.');if(!$lines)throw new DomainException('Additional Stock request needs product lines.');$db=Db::wpdb();$pending=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_requests')." WHERE daily_cycle_id=%d AND type='additional' AND status IN ('draft','submitted','reviewed','approved','awaiting_receipt')",$id));if($pending)throw new DomainException('A pending Additional Stock request already exists.','additional_request_pending',409);$prepared=[];$seen=[];foreach($lines as$x){$pid=(int)($x['product_id']??0);$qty=(float)($x['quantity']??0);if(!$pid||$qty<=0)throw new DomainException('Invalid additional line.');if(isset($seen[$pid]))throw new DomainException('Duplicate product in Additional Stock request.','duplicate_daily_line',422);$seen[$pid]=1;StockService::product($a,$pid);$prepared[]=['product_id'=>$pid,'quantity'=>$qty];}Db::mustInsert($db,Db::table('daily_requests'),['daily_cycle_id'=>$id,'type'=>'additional','status'=>'submitted','requested_by'=>$a->employeeId,'created_at'=>Db::now()]);$rid=(int)$db->insert_id;foreach($prepared as$x)Db::mustInsert($db,Db::table('daily_request_lines'),['daily_request_id'=>$rid,'product_id'=>$x['product_id'],'batch_id'=>null,'quantity'=>$x['quantity']]);Audit::add($a,'daily_order.additional','daily_request',$rid,['branch_id'=>(int)$c['branch_id'],'cycle_id'=>$id]);return['id'=>$rid,'cycle_id'=>$id,'status'=>'submitted'];});}
 public static function review(Actor $a,int $request):array{
  return Transaction::run(function()use($a,$request){
   $db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,c.branch_id,c.employee_id,c.company_id,c.business_date FROM ".Db::table('daily_requests')." r JOIN ".Db::table('daily_cycles')." c ON c.id=r.daily_cycle_id WHERE r.id=%d AND c.company_id=%d FOR UPDATE",$request,$a->companyId),ARRAY_A);
   if(!$r)throw new DomainException('Daily request not found.','daily_request_not_found',404);
   Guard::branch($a,(int)$r['branch_id'],Capabilities::DAILY_OTHERS);
   $designation=strtoupper(trim($a->designationCode));
   if(!in_array($designation,['SM','SALES_MANAGER','ASM','ASSISTANT_SALES_MANAGER','SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR'],true))throw new DomainException('Independent SM/ASM reviewer required.','daily_reviewer_required',403);
   if($a->employeeId===(int)$r['requested_by']||$a->employeeId===(int)$r['employee_id'])throw new DomainException('Maker or beneficiary cannot review their request.','maker_checker_required',409);
   BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['business_date']);
   if($r['status']!=='submitted')throw new DomainException('Request is not submitted.','daily_request_state_invalid',409);
   Db::mustUpdate($db,Db::table('daily_requests'),['status'=>'reviewed','reviewed_by'=>$a->employeeId,'reviewed_at'=>Db::now()],['id'=>$request]);
   Audit::add($a,'daily_order.review','daily_request',$request,['branch_id'=>(int)$r['branch_id']]);
   return['id'=>$request,'status'=>'reviewed'];
  });
 }
 public static function approve(Actor $a,int $request):array{return Transaction::run(function()use($a,$request){$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,c.branch_id,c.employee_id,c.company_id,c.business_date FROM ".Db::table('daily_requests')." r JOIN ".Db::table('daily_cycles')." c ON c.id=r.daily_cycle_id WHERE r.id=%d AND c.company_id=%d FOR UPDATE",$request,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Daily request not found.');$authority=ActingDutyService::assertAction($a,(int)$r['branch_id'],'daily.approve',(int)$r['requested_by']);if($authority['mode']==='permanent')HierarchyScope::assertCanViewEmployee($a,(int)$r['employee_id']);BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['business_date']);if($r['status']!=='reviewed')throw new DomainException('Independent review required before final approval.','daily_review_required',409);
 $designation=strtoupper(trim($a->designationCode));
 if(!in_array($designation,['BM','BRANCH_MANAGER','ZI','ZONAL_INSPECTOR','RC','REGIONAL_COORDINATOR','RM','REGIONAL_MANAGER','AGM','ASSISTANT_GENERAL_MANAGER','SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR'],true))throw new DomainException('Branch approver role is required.','daily_final_approver_required',403);
 if(in_array($a->employeeId,[(int)$r['requested_by'],(int)$r['employee_id'],(int)$r['reviewed_by']],true))throw new DomainException('Maker, beneficiary or reviewer cannot final-approve.','maker_checker_required',409);Db::mustUpdate($db,Db::table('daily_requests'),['status'=>'approved','approved_by'=>$a->employeeId,'approved_at'=>Db::now()],['id'=>$request]);if($r['type']==='initial')Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'approved'],['id'=>(int)$r['daily_cycle_id']]);return['id'=>$request,'status'=>'approved'];});}
 public static function issue(Actor $a,int $request,array $alloc):array{
  return Transaction::run(function()use($a,$request,$alloc){
   $db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,c.branch_id,c.employee_id,c.company_id,c.business_date FROM ".Db::table('daily_requests')." r JOIN ".Db::table('daily_cycles')." c ON c.id=r.daily_cycle_id WHERE r.id=%d AND c.company_id=%d FOR UPDATE",$request,$a->companyId),ARRAY_A);
   if(!$r)throw new DomainException('Daily request not found.','daily_request_not_found',404);
   $authority=ActingDutyService::assertAction($a,(int)$r['branch_id'],'daily.issue',(int)$r['requested_by']);
   if($authority['mode']==='permanent')HierarchyScope::assertCanViewEmployee($a,(int)$r['employee_id']);
   BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['business_date']);
   if($r['status']!=='approved')throw new DomainException('Request not finally approved.','daily_request_state_invalid',409);
   if($a->employeeId===(int)$r['employee_id']||$a->employeeId===(int)$r['requested_by'])throw new DomainException('Beneficiary or maker cannot allocate own stock.','maker_checker_required',409);
   $wanted=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('daily_request_lines')." WHERE daily_request_id=%d",$request),ARRAY_A);
   $wantedIds=[];foreach($wanted as$w)$wantedIds[(int)$w['id']]=true;
   $map=[];foreach($alloc as$x){$lineId=(int)($x['request_line_id']??0);if(!isset($wantedIds[$lineId]))throw new DomainException('Unknown issue request line.','daily_allocation_invalid',422);$map[$lineId][]=$x;}
   foreach($wanted as$w){
    $parts=$map[(int)$w['id']]??[];if(!$parts)throw new DomainException('Every request line needs allocation.','daily_allocation_invalid',422);
    $sum=0.;foreach($parts as$x){$qty=(float)($x['quantity']??0);if($qty<=0||!is_finite($qty))throw new DomainException('Positive allocation quantity required.','daily_allocation_invalid',422);$sum+=$qty;}
    if(abs($sum-(float)$w['quantity'])>.0001)throw new DomainException('Issue allocation must equal requested quantity.','daily_allocation_invalid',422);
    $p=StockService::product($a,(int)$w['product_id']);$com=StockService::commercial($a,(int)$w['product_id']);
    foreach($parts as$x){
     $batch=isset($x['batch_id'])?(int)$x['batch_id']:null;$qty=(float)$x['quantity'];
     $slices=$batch?[['batch_id'=>$batch,'quantity'=>$qty]]:StockService::automaticCustodyAllocations($a,(int)$r['branch_id'],(int)$w['product_id'],$qty);
     foreach($slices as$slice){
      $sliceBatch=$slice['batch_id']!==null?(int)$slice['batch_id']:null;$sliceQty=(float)$slice['quantity'];
      StockService::validateBatch($a,$p,$sliceBatch,true);
      $cost=StockService::cost($a,(int)$r['branch_id'],(int)$w['product_id'],$sliceBatch,null);
      Db::mustInsert($db,Db::table('daily_issue_lines'),['daily_request_id'=>$request,'product_id'=>(int)$w['product_id'],'batch_id'=>$sliceBatch,'quantity'=>$sliceQty,'sale_price_snapshot'=>(float)$com['sale_price'],'ho_amount_snapshot'=>(float)$com['ho_amount'],'bm_profit_snapshot'=>(float)$com['bm_profit'],'office_expense_snapshot'=>(float)$com['office_expense'],'points_snapshot'=>(float)$com['points'],'salary_fund_snapshot'=>(float)$com['salary_fund'],'purchase_cost_snapshot'=>$cost]);
     }
    }
   }
   Db::mustUpdate($db,Db::table('daily_requests'),['status'=>'awaiting_receipt','issued_by'=>$a->employeeId,'allocated_at'=>Db::now()],['id'=>$request]);
   if($r['type']==='initial')Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'awaiting_receipt'],['id'=>(int)$r['daily_cycle_id']]);
   Audit::add($a,'daily_order.allocate','daily_request',$request,['branch_id'=>(int)$r['branch_id'],'employee_id'=>(int)$r['employee_id']]);
   return['id'=>$request,'status'=>'awaiting_receipt'];
  });
 }
 public static function receive(Actor $a,int $request):array{
  return Transaction::run(function()use($a,$request){
   $db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,c.branch_id,c.employee_id,c.company_id,c.business_date FROM ".Db::table('daily_requests')." r JOIN ".Db::table('daily_cycles')." c ON c.id=r.daily_cycle_id WHERE r.id=%d AND c.company_id=%d FOR UPDATE",$request,$a->companyId),ARRAY_A);
   if(!$r)throw new DomainException('Daily request not found.','daily_request_not_found',404);
   Guard::branch($a,(int)$r['branch_id'],Capabilities::DAILY_SELF);
   if($a->employeeId!==(int)$r['employee_id'])throw new DomainException('Only the beneficiary may confirm physical receipt.','daily_receipt_forbidden',403);
   BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['business_date']);
   if($r['status']!=='awaiting_receipt')throw new DomainException('Request not awaiting physical receipt.','daily_request_state_invalid',409);
   $lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('daily_issue_lines')." WHERE daily_request_id=%d ORDER BY id FOR UPDATE",$request),ARRAY_A);
   if(!$lines)throw new DomainException('No stock allocations available.','daily_allocation_missing',409);
   foreach($lines as$l){
    $batch=$l['batch_id']!==null?(int)$l['batch_id']:null;
    $cost=StockService::transferCustody($a,(int)$r['branch_id'],(int)$r['employee_id'],(int)$l['product_id'],$batch,(float)$l['quantity'],'daily_issue',$request);
    Db::mustUpdate($db,Db::table('daily_issue_lines'),['purchase_cost_snapshot'=>$cost],['id'=>(int)$l['id']]);
   }
   Db::mustUpdate($db,Db::table('daily_requests'),['status'=>'issued','received_by'=>$a->employeeId,'received_at'=>Db::now(),'issued_at'=>Db::now()],['id'=>$request]);
   if($r['type']==='initial')Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'issued'],['id'=>(int)$r['daily_cycle_id']]);
   Audit::add($a,'daily_order.receipt','daily_request',$request,['branch_id'=>(int)$r['branch_id'],'employee_id'=>$a->employeeId]);
   return['id'=>$request,'status'=>'issued'];
  });
 }
 public static function eveningStart(Actor $a,int $id):array{return Transaction::run(function()use($a,$id){$c=self::cycle($a,$id,true);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;Guard::branch($a,(int)$c['branch_id'],$cap);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='issued')throw new DomainException('Evening can start only after issue.');$db=Db::wpdb();$pending=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_requests')." WHERE daily_cycle_id=%d AND type='additional' AND status IN ('draft','submitted','reviewed','approved','awaiting_receipt')",$id));if($pending)throw new DomainException('Pending Additional Stock request must be completed first.','additional_request_pending',409);$existing=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d",$id));if($existing)throw new DomainException('Evening Settlement already exists.','evening_exists',409);Db::mustInsert($db,Db::table('evening_settlements'),['daily_cycle_id'=>$id,'status'=>'draft','created_at'=>Db::now()]);$eid=(int)$db->insert_id;$issues=(array)$db->get_results($db->prepare("SELECT il.* FROM ".Db::table('daily_issue_lines')." il JOIN ".Db::table('daily_requests')." r ON r.id=il.daily_request_id WHERE r.daily_cycle_id=%d",$id),ARRAY_A);foreach($issues as$l)Db::mustInsert($db,Db::table('evening_lines'),['evening_settlement_id'=>$eid,'issue_line_id'=>(int)$l['id'],'product_id'=>(int)$l['product_id'],'batch_id'=>$l['batch_id'],'issued_quantity'=>(float)$l['quantity'],'return_quantity'=>0,'retail_quantity'=>(float)$l['quantity'],'wholesale_quantity'=>0,'retail_rate'=>(float)$l['sale_price_snapshot'],'wholesale_rate'=>0,'total_amount'=>round((float)$l['quantity']*(float)$l['sale_price_snapshot'],2),'ho_amount'=>round((float)$l['quantity']*(float)$l['ho_amount_snapshot'],2),'bm_profit'=>round((float)$l['quantity']*(float)$l['bm_profit_snapshot'],2),'office_expense'=>round((float)$l['quantity']*(float)$l['office_expense_snapshot'],2),'points'=>round((float)$l['quantity']*(float)$l['points_snapshot'],2),'salary_fund'=>round((float)$l['quantity']*(float)$l['salary_fund_snapshot'],2),'purchase_cost_snapshot'=>(float)$l['purchase_cost_snapshot']]);Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'evening_draft'],['id'=>$id]);return['id'=>$id,'evening_id'=>$eid,'status'=>'evening_draft'];});}
 public static function eveningSave(Actor $a,int $id,array $lines,array $wholesale,string $priceReason):array{
  return Transaction::run(function()use($a,$id,$lines,$wholesale,$priceReason){
   $c=self::cycle($a,$id,true);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;Guard::branch($a,(int)$c['branch_id'],$cap);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='evening_draft')throw new DomainException('Evening not editable.');
   $db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d FOR UPDATE",$id),ARRAY_A);if(!$e||$e['status']!=='draft')throw new DomainException('Evening Settlement is not draft.','evening_state_invalid',409);
   $stored=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('evening_lines')." WHERE evening_settlement_id=%d ORDER BY id FOR UPDATE",(int)$e['id']),ARRAY_A);
   $map=[];foreach($lines as$x){$issueLine=(int)($x['issue_line_id']??0);if($issueLine<1||isset($map[$issueLine]))throw new DomainException('Every issued line must be supplied exactly once.','evening_line_invalid',422);$map[$issueLine]=$x;}if(count($map)!==count($stored))throw new DomainException('Every issued line must be verified exactly once.','evening_line_missing',422);
   $expected=0.0;$hasWholesale=false;
   foreach($stored as$r){
    $x=$map[(int)$r['issue_line_id']]??throw new DomainException('Issued line missing from Evening Settlement.','evening_line_missing',422);$issued=(float)$r['issued_quantity'];$ret=(float)($x['return_quantity']??0);$wh=(float)($x['wholesale_quantity']??0);
    if(!is_finite($ret)||!is_finite($wh)||$ret<0||$wh<0)throw new DomainException('Return and wholesale quantities cannot be negative.','evening_quantity_invalid',422);$retail=FieldSalesRules::retailQuantity($issued,$ret,$wh);$rr=(float)($x['retail_rate']??$r['retail_rate']);$wr=(float)($x['wholesale_rate']??0);$approved=(float)$r['retail_rate'];if(abs($rr-$approved)>.005)throw new DomainException('Retail rate cannot change without approved pricing authority.','price_authority_required',409);if($rr<0||$wr<0||($wh>0&&($wr<=0||$wr>$rr)))throw new DomainException('Invalid retail/wholesale sale rate.');
    if($wh>0&&abs($wr-$rr)>.005)throw new DomainException('Wholesale discount requires approved B2B/Distributor pricing workflow.','wholesale_pricing_approval_required',409);$amount=round($retail*$rr+$wh*$wr,2);$factor=$issued>0?($retail+$wh)/$issued:0;$ho=round((float)$r['ho_amount']*$factor,2);$bm=round((float)$r['bm_profit']*$factor,2);$expense=round((float)$r['office_expense']*$factor,2);$points=round((float)$r['points']*$factor,2);$salary=round((float)$r['salary_fund']*$factor,2);
