 public static function eveningSubmit(Actor $a,int $id):array{
  return Transaction::run(function()use($a,$id){
   $c=self::cycle($a,$id,true);$cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;Guard::branch($a,(int)$c['branch_id'],$cap);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='evening_draft')throw new DomainException('Evening not draft.');
   $db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d FOR UPDATE",$id),ARRAY_A);if(!$e||$e['status']!=='draft')throw new DomainException('Evening Settlement is not draft.','evening_state_invalid',409);
   if(empty($e['reconciled_at']))throw new DomainException('Evening reconciliation must be saved before submission.','evening_reconciliation_required',409);
   $recon=$db->get_row($db->prepare("SELECT COUNT(*) line_count,COALESCE(SUM(total_amount),0) computed_total,COALESCE(SUM(CASE WHEN ABS(issued_quantity-return_quantity-retail_quantity-wholesale_quantity)>.0001 OR return_quantity<0 OR retail_quantity<0 OR wholesale_quantity<0 THEN 1 ELSE 0 END),0) invalid_lines FROM ".Db::table('evening_lines')." WHERE evening_settlement_id=%d",(int)$e['id']),ARRAY_A);
   if(!$recon||(int)$recon['line_count']<1||(int)$recon['invalid_lines']>0||abs((float)$recon['computed_total']-(float)$e['expected_amount'])>.005)throw new DomainException('Evening quantities or payment totals do not reconcile.','evening_reconciliation_mismatch',409);
   Db::mustUpdate($db,Db::table('evening_settlements'),['status'=>'submitted','submitted_by'=>$a->employeeId,'submitted_at'=>Db::now()],['id'=>(int)$e['id']]);
   Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'evening_submitted'],['id'=>$id]);
   return['id'=>$id,'status'=>'evening_submitted','expected_amount'=>(float)$e['expected_amount']];
  });
 }
 public static function recordUpi(Actor $a,int $id,string $reference,float $amount):array{
  return Transaction::run(function()use($a,$id,$reference,$amount){
   $c=self::cycle($a,$id,true);
   $cap=(int)$c['employee_id']===$a->employeeId?Capabilities::DAILY_SELF:Capabilities::DAILY_OTHERS;
   Guard::branch($a,(int)$c['branch_id'],$cap);
   if((int)$c['employee_id']!==$a->employeeId)HierarchyScope::assertCanViewEmployee($a,(int)$c['employee_id']);
   BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);
   if(!in_array($c['status'],['issued','evening_draft','evening_submitted'],true))throw new DomainException('Daily cycle not open for UPI receipts.','upi_cycle_state_invalid',409);
   $reference=trim($reference);
   if(strlen($reference)<6||strlen($reference)>120||!preg_match('/^[A-Za-z0-9_\/-]+$/D',$reference))throw new DomainException('Valid UPI transaction reference required.','upi_reference_invalid',422);
   if(!is_finite($amount)||$amount<=0)throw new DomainException('UPI amount must be positive.','upi_amount_invalid',422);
   $db=Db::wpdb();Db::mustInsert($db,Db::table('daily_upi_receipts'),['company_id'=>$a->companyId,'branch_id'=>(int)$c['branch_id'],'daily_cycle_id'=>$id,'reference'=>$reference,'amount'=>round($amount,2),'status'=>'pending','received_by'=>$a->employeeId,'created_at'=>Db::now()],'UPI transaction reference already recorded.','upi_reference_duplicate');
   $receiptId=(int)$db->insert_id;
   Audit::add($a,'daily_upi.record','daily_upi_receipt',$receiptId,['daily_cycle_id'=>$id,'branch_id'=>(int)$c['branch_id'],'amount'=>round($amount,2)]);
   return['id'=>$receiptId,'status'=>'pending'];
  });
 }
 public static function decideUpi(Actor $a,int $receiptId,bool $approve,string $bankEvidence,string $reason):array{
  Guard::cap($a,Capabilities::BANK_RECONCILE);
  return Transaction::run(function()use($a,$receiptId,$approve,$bankEvidence,$reason){
   $db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('daily_upi_receipts')." WHERE id=%d AND company_id=%d FOR UPDATE",$receiptId,$a->companyId),ARRAY_A);
   if(!$r)throw new DomainException('UPI receipt not found.','upi_receipt_not_found',404);
   Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);
   if($r['status']!=='pending')throw new DomainException('UPI receipt already decided.','upi_receipt_state_invalid',409);
   if((int)$r['received_by']===$a->employeeId)throw new DomainException('UPI collector cannot verify own receipt.','maker_checker_required',409);
   $cycle=self::cycle($a,(int)$r['daily_cycle_id'],true);
   if($cycle['status']==='completed')throw new DomainException('Completed daily cycle is locked.','upi_cycle_state_invalid',409);
   $bankEvidence=trim($bankEvidence);$reason=trim($reason);
   if($approve&&strlen($bankEvidence)<6)throw new DomainException('Bank statement evidence reference is required.','upi_bank_evidence_required',422);
   if($approve&&strlen($bankEvidence)>120)throw new DomainException('Bank evidence reference too long.','upi_bank_evidence_invalid',422);
   if(!$approve&&strlen($reason)<5)throw new DomainException('Rejection reason required.','upi_reject_reason_required',422);
   if($approve&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_upi_receipts')." WHERE company_id=%d AND bank_evidence_ref=%s AND id<>%d",$a->companyId,$bankEvidence,$receiptId))>0)throw new DomainException('Bank evidence is already assigned to another UPI receipt.','upi_bank_evidence_duplicate',409);
   Db::mustUpdate($db,Db::table('daily_upi_receipts'),['status'=>$approve?'verified':'rejected','bank_evidence_ref'=>$approve?$bankEvidence:null,'reason'=>$approve?null:$reason,'verified_by'=>$a->employeeId,'verified_at'=>Db::now()],['id'=>$receiptId]);
   Audit::add($a,'daily_upi.decision','daily_upi_receipt',$receiptId,['daily_cycle_id'=>(int)$r['daily_cycle_id'],'status'=>$approve?'verified':'rejected']);
   return['id'=>$receiptId,'status'=>$approve?'verified':'rejected'];
  });
 }
 public static function finalPost(Actor $a,int $id,float $cash,float $upi):array{return Transaction::run(function()use($a,$id,$cash,$upi){$c=self::cycle($a,$id,true);BranchDayGuard::assertOpen($a,(int)$c['branch_id'],(string)$c['business_date']);if($c['status']!=='evening_submitted')throw new DomainException('Daily Order not ready for final post.');$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d FOR UPDATE",$id),ARRAY_A);if(!$e||$e['status']!=='submitted')throw new DomainException('Submitted Evening Settlement not found.','evening_state_invalid',409);$authority=ActingDutyService::assertAction($a,(int)$c['branch_id'],'daily.final_post',(int)$e['submitted_by']);if($authority['mode']==='permanent'&&(int)$c['employee_id']!==$a->employeeId)HierarchyScope::assertCanViewEmployee($a,(int)$c['employee_id']);$expected=round((float)$e['expected_amount'],2);if((int)$e['submitted_by']===$a->employeeId)throw new DomainException('Evening maker cannot final-post own settlement.','maker_checker_required',409);FieldSalesRules::requireExactCollection($expected,$cash,$upi);
 $upiInfo=$db->get_row($db->prepare("SELECT COALESCE(SUM(CASE WHEN status='verified' THEN amount ELSE 0 END),0) verified_amount,COALESCE(SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END),0) pending_count FROM ".Db::table('daily_upi_receipts')." WHERE company_id=%d AND daily_cycle_id=%d",$a->companyId,$id),ARRAY_A);
 if((int)($upiInfo['pending_count']??0)>0||abs((float)($upiInfo['verified_amount']??0)-$upi)>.005)throw new DomainException('UPI collection must match independently verified bank evidence before final posting.','upi_verification_required',409);
 $lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('evening_lines')." WHERE evening_settlement_id=%d",(int)$e['id']),ARRAY_A);$points=0.0;$salary=0.0;$cogs=0.0;foreach($lines as$l){$batch=$l['batch_id']!==null?(int)$l['batch_id']:null;$ret=(float)$l['return_quantity'];$sold=(float)$l['retail_quantity']+(float)$l['wholesale_quantity'];$cost=(float)$l['purchase_cost_snapshot'];if($ret>0){StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'OUT',$ret,$cost,'daily_return',$id);StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,null,'IN',$ret,$cost,'daily_return',$id);}if($sold>0)StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'OUT',$sold,$cost,'daily_sale',$id);$points+=(float)$l['points'];$salary+=(float)$l['salary_fund'];$cogs+=round($sold*$cost,2);} $settings=(array)$db->get_results($db->prepare("SELECT setting_key,setting_value FROM ".Db::table('settings')." WHERE company_id=%d AND setting_key IN ('daily_cash_account_id','daily_upi_account_id')",$a->companyId),ARRAY_A);$map=[];foreach($settings as$s)$map[$s['setting_key']]=(int)$s['setting_value'];if(($cash>0&&!isset($map['daily_cash_account_id']))||($upi>0&&!isset($map['daily_upi_account_id'])))throw new DomainException('Daily payment accounts not configured.','payment_accounts_missing',409);if($cash>0){$cashAcc=AccountingService::paymentAccount($a,(int)$map['daily_cash_account_id']);if(strtolower((string)$cashAcc['subtype'])!=='cash')throw new DomainException('Daily Cash account must be Cash ledger.','payment_account_invalid',409);}if($upi>0){$upiAcc=AccountingService::paymentAccount($a,(int)$map['daily_upi_account_id']);if(strtolower((string)$upiAcc['subtype'])!=='upi')throw new DomainException('Daily UPI account must be UPI ledger.','payment_account_invalid',409);}$sales=AccountingService::accountByCode($a,'SALES');$cogsA=AccountingService::accountByCode($a,'COGS');$inv=AccountingService::accountByCode($a,'INVENTORY');$jl=[];if($cash>0)$jl[]=['account_id'=>$map['daily_cash_account_id'],'debit'=>$cash];if($upi>0)$jl[]=['account_id'=>$map['daily_upi_account_id'],'debit'=>$upi];$jl[]=['account_id'=>(int)$sales['id'],'credit'=>$expected];if($cogs>0){$jl[]=['account_id'=>(int)$cogsA['id'],'debit'=>$cogs];$jl[]=['account_id'=>(int)$inv['id'],'credit'=>$cogs];}$journal=AccountingService::post($a,(int)$c['branch_id'],'daily_cycle',$id,$c['business_date'].' 23:59:59',$jl,'Daily Order final post');Db::mustInsert($db,Db::table('performance_entries'),['company_id'=>$a->companyId,'branch_id'=>(int)$c['branch_id'],'employee_id'=>(int)$c['employee_id'],'business_date'=>$c['business_date'],'source_type'=>'daily_cycle','source_id'=>$id,'points'=>round($points,2),'salary_fund'=>round($salary,2),'created_at'=>Db::now()]);Db::mustUpdate($db,Db::table('evening_settlements'),['status'=>'posted','cash_amount'=>$cash,'upi_amount'=>$upi,'reviewed_by'=>$a->employeeId,'reviewed_at'=>Db::now()],['id'=>(int)$e['id']]);Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'completed','completed_at'=>Db::now()],['id'=>$id]);Audit::add($a,'daily_order.final_post','daily_cycle',$id,['branch_id'=>(int)$c['branch_id'],'amount'=>$expected,'journal_id'=>$journal]);return['id'=>$id,'status'=>'completed','amount'=>$expected,'points'=>round($points,2),'salary_fund'=>round($salary,2)];});}
 private static function cycle(Actor $a,int $id,bool $lock=false):array{$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('daily_cycles')." WHERE id=%d AND company_id=%d".($lock?' FOR UPDATE':''),$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Daily Order not found.','daily_not_found',404);return$r;}
